        if(!$this->ok($s)||'imperium.oracle-model-intelligence-snapshot/v1'!==($s['schema']??null)||$snapshotId!==($s['snapshot_id']??null)||'ORACLE_CANONICAL_CATALOGUE_SNAPSHOT_SEALED_NO_SELECTION_AUTHORITY'!==($s['status']??null)||true===($s['selection_authority']??null)
            ||!$this->ok($c)||'imperium.curia-seneschal-occupancy/v1'!==($c['schema']??null)||$seneschalBindingId!==($c['binding_id']??null)||($s['instance_id']??null)!==($c['instance_id']??null)||'curia.seneschal'!==($c['seat']??null)||'ACTIVE'!==($c['status']??null)||true!==($c['model_requirement_commission_authority']??null)||true===($c['execution_authority']??null)
