        $id='model-requirement-commission-'.substr(hash('sha256',CanonicalJson::encode([$s['instance_id'],$snapshotId,$s['record_digest'],$issuer,$target,$criteria,$issuedAt->format(DATE_ATOM),$expiresAt->format(DATE_ATOM)])),0,20);
