    }
    private function target(array$t):array{if(array_keys($t)!==['type','id','mission_id']||!in_array($t['type']??null,['OFFICE_SEAT','MISSION_FUNCTION'],true)||!$this->text($t['id']??null)||!(null===$t['mission_id']||$this->text($t['mission_id'])))throw new \InvalidArgumentException('C234_MODEL_REQUIREMENT_TARGET_INVALID');if('MISSION_FUNCTION'===$t['type']&&null===$t['mission_id'])throw new \InvalidArgumentException('C234_MODEL_REQUIREMENT_TARGET_INVALID');return$t;}
